# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SÜBHANEKE DUASI VE TEVHİD VURGUSU</text>\n  <rect x="50" y="55" width="600" height="95" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="350" y="80" text-anchor="middle" font-size="14" font-weight="bold" fill="#1d4ed8">Sübhaneke Duasının Okunuşu</text>\n  <text x="350" y="105" text-anchor="middle" font-size="12" fill="#1e3a8a">Sübhânekellâhümme ve bi hamdik ve tebârakesmük ve teâlâ ceddük</text>\n  <text x="350" y="130" text-anchor="middle" font-size="12" fill="#1e3a8a">(ve celle senâük*) ve lâ ilâhe ğayrük.</text>\n  <rect x="50" y="160" width="600" height="75" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="185" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Temel Mesajı ve Anlamı</text>\n  <text x="350" y="205" text-anchor="middle" font-size="11.5" fill="#334155">"Allah\'ım! Sen her türlü eksiklikten uzaksın. Seni hamdinle överim. İsmin mübarektir,</text>\n  <text x="350" y="223" text-anchor="middle" font-size="11.5" fill="#334155">şanın yücedir. Senden başka hiçbir ilah yoktur."</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">RABBENA DUALARI (DÜNYA VE AHİRET İYİLİĞİ)</text>\n  <rect x="35" y="55" width="305" height="180" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="187" y="82" text-anchor="middle" font-size="14" font-weight="bold" fill="#1d4ed8">Rabbenâ Âtinâ (Bakara, 201)</text>\n  <text x="187" y="110" text-anchor="middle" font-size="12" font-style="italic" fill="#1e3a8a">"Rabbenâ âtinâ fi\'d-dünyâ haseneten</text>\n  <text x="187" y="130" text-anchor="middle" font-size="12" font-style="italic" fill="#1e3a8a">ve fi\'l-âhirati haseneten ve kınâ azâbe\'n-nâr."</text>\n  <text x="187" y="165" text-anchor="middle" font-size="11" fill="#334155">Ey Rabbimiz! Bize dünyada da iyilik ver,</text>\n  <text x="187" y="185" text-anchor="middle" font-size="11" fill="#334155">ahirette de iyilik ver ve bizi ateş azabından koru!</text>\n  <text x="187" y="215" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">Dünya ve ahiret dengesi</text>\n  <rect x="360" y="55" width="305" height="180" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="512" y="82" text-anchor="middle" font-size="14" font-weight="bold" fill="#15803d">Rabbenâğfirlî (İbrâhîm, 41)</text>\n  <text x="512" y="110" text-anchor="middle" font-size="12" font-style="italic" fill="#14532d">"Rabbenagfirlî ve li-vâlideyye</text>\n  <text x="512" y="130" text-anchor="middle" font-size="12" font-style="italic" fill="#14532d">ve li\'l-mü\'minîne yevme yekûmü\'l-hisâb."</text>\n  <text x="512" y="165" text-anchor="middle" font-size="11" fill="#334155">Ey Rabbimiz! Hesabın görüleceği gün;</text>\n  <text x="512" y="185" text-anchor="middle" font-size="11" fill="#334155">beni, anamı-babamı ve müminleri bağışla!</text>\n  <text x="512" y="215" text-anchor="middle" font-size="11" font-weight="bold" fill="#16a34a">Vefa, anne-baba ve kardeşlik duası</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">DUALARIN NAMAZDAKİ VE HAYATTAKİ YERİ</text>\n  <rect x="40" y="60" width="190" height="175" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="135" y="85" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Namazın Başlangıcı</text>\n  <text x="135" y="115" text-anchor="middle" font-size="11" fill="#334155">İftitah tekbirinden sonra</text>\n  <text x="135" y="135" text-anchor="middle" font-size="11" fill="#334155">ilk olarak Sübhaneke okunur.</text>\n  <text x="135" y="160" text-anchor="middle" font-size="11" fill="#334155">Allah\'a tazim ve övgü ile</text>\n  <text x="135" y="180" text-anchor="middle" font-size="11" fill="#334155">namaza başlanır.</text>\n  <text x="135" y="210" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">Giriş Kapısı</text>\n  <rect x="255" y="60" width="190" height="175" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="350" y="85" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Son Oturuş (Kade-i Âhire)</text>\n  <text x="350" y="115" text-anchor="middle" font-size="11" fill="#334155">Salli-Barik dualarından sonra</text>\n  <text x="350" y="135" text-anchor="middle" font-size="11" fill="#334155">Rabbena duaları okunur.</text>\n  <text x="350" y="160" text-anchor="middle" font-size="11" fill="#334155">Selam vermeden hemen önce</text>\n  <text x="350" y="180" text-anchor="middle" font-size="11" fill="#334155">af ve iyilik istenir.</text>\n  <text x="350" y="210" text-anchor="middle" font-size="11" font-weight="bold" fill="#ca8a04">Huzurdan Ayrılış</text>\n  <rect x="470" y="60" width="190" height="175" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="565" y="85" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Günlük Yaşamda Dua</text>\n  <text x="565" y="115" text-anchor="middle" font-size="11" fill="#334155">Her namaz ardından,</text>\n  <text x="565" y="135" text-anchor="middle" font-size="11" fill="#334155">hac ve umrede tavafta,</text>\n  <text x="565" y="160" text-anchor="middle" font-size="11" fill="#334155">anne-babaya vefada</text>\n  <text x="565" y="180" text-anchor="middle" font-size="11" fill="#334155">daima dilimizdedir.</text>\n  <text x="565" y="210" text-anchor="middle" font-size="11" font-weight="bold" fill="#16a34a">Sürekli Niyaz</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
